// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title MultiSigTreasury
 * @author Aethelred Team
 * @notice Institutional treasury governance contract for the NoblePay cross-border
 *         payment platform. Provides N-of-M multi-signature operations with tiered
 *         approval thresholds, time-locked execution, spending policy enforcement,
 *         budget tracking, recurring payments, and DeFi yield allocation.
 *
 * @dev Architecture overview:
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │                    MULTISIG TREASURY                              │
 * ├───────────────────────────────────────────────────────────────────┤
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Proposals       │  │  Approval Tiers   │  │  Time Locks    │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • create        │  │  • small: 2/5     │  │  • 24hr small  │  │
 * │  │  • approve       │  │  • medium: 3/5    │  │  • 48hr large  │  │
 * │  │  • reject        │  │  • large: 4/5     │  │  • fast-track  │  │
 * │  │  • execute       │  │  • emergency      │  │  • emergency   │  │
 * │  │  • cancel        │  │                    │  │                │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Budgets         │  │  Recurring Pay    │  │  Yield Mgmt    │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • dept alloc    │  │  • standing orders│  │  • DeFi alloc  │  │
 * │  │  • spending cap  │  │  • authorization  │  │  • approved    │  │
 * │  │  • daily/weekly  │  │  • auto-execute   │  │    protocols   │  │
 * │  │  • monthly       │  │  • revocation     │  │  • rebalance   │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * Approval thresholds (configurable, defaults for 5 signers):
 *   - Small  (< $10K):  2 of 5  |  24-hour timelock
 *   - Medium ($10K-$100K): 3 of 5  |  24-hour timelock
 *   - Large  (> $100K): 4 of 5  |  48-hour timelock
 *   - Emergency:       4 of 5  |  1-hour timelock (fast-track)
 */
contract MultiSigTreasury is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ──────────────────────────────────────────────────────────────
    // Roles
    // ──────────────────────────────────────────────────────────────

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant SIGNER_ROLE = keccak256("SIGNER_ROLE");
    bytes32 public constant BUDGET_MANAGER_ROLE = keccak256("BUDGET_MANAGER_ROLE");
    bytes32 public constant YIELD_MANAGER_ROLE = keccak256("YIELD_MANAGER_ROLE");

    // ──────────────────────────────────────────────────────────────
    // Enums
    // ──────────────────────────────────────────────────────────────

    /// @notice Proposal lifecycle status.
    enum ProposalStatus {
        PENDING,
        APPROVED,
        EXECUTED,
        REJECTED,
        CANCELLED,
        EXPIRED
    }

    /// @notice Transaction size tier determining approval requirements.
    enum TxTier {
        SMALL,
        MEDIUM,
        LARGE,
        EMERGENCY
    }

    /// @notice Spending category for budget tracking.
    enum SpendingCategory {
        OPERATIONS,
        PAYROLL,
        INFRASTRUCTURE,
        MARKETING,
        LEGAL,
        RESEARCH,
        PARTNERSHIPS,
        OTHER
    }

    /// @notice Recurring payment frequency.
    enum PaymentFrequency {
        DAILY,
        WEEKLY,
        BIWEEKLY,
        MONTHLY,
        QUARTERLY
    }

    // ──────────────────────────────────────────────────────────────
    // Structs
    // ──────────────────────────────────────────────────────────────

    /// @notice Treasury transfer proposal.
    struct Proposal {
        bytes32 proposalId;
        address proposer;
        address recipient;
        address token;               // ERC20 token; address(0) for native
        uint256 amount;
        SpendingCategory category;
        string description;
        TxTier tier;
        ProposalStatus status;
        uint256 approvalCount;
        uint256 rejectionCount;
        uint256 requiredApprovals;
        uint256 createdAt;
        uint256 timelockExpiry;      // Earliest execution timestamp
        uint256 expiresAt;           // Proposal expiry (auto-cancel)
        bool isEmergency;
        bytes32 budgetId;            // Associated budget (0x0 if none)
    }

    /// @notice Budget allocation for a department or project.
    struct Budget {
        bytes32 budgetId;
        string name;
        SpendingCategory category;
        uint256 totalAllocation;     // Total budget in USD-equiv (6 dec)
        uint256 spent;               // Amount spent so far
        uint256 dailyLimit;
        uint256 weeklyLimit;
        uint256 monthlyLimit;
        uint256 createdAt;
        uint256 periodStart;         // Start of current budget period
        uint256 periodEnd;           // End of current budget period
        bool active;
    }

    /// @notice Daily/weekly/monthly spending tracker for a budget.
    struct SpendingTracker {
        uint256 dailySpent;
        uint256 weeklySpent;
        uint256 monthlySpent;
        uint256 lastDayReset;
        uint256 lastWeekReset;
        uint256 lastMonthReset;
    }

    /// @notice Recurring payment authorization (standing order).
    struct RecurringPayment {
        bytes32 paymentId;
        address recipient;
        address token;
        uint256 amount;
        PaymentFrequency frequency;
        SpendingCategory category;
        string description;
        uint256 nextExecution;
        uint256 lastExecuted;
        uint256 executionCount;
        uint256 maxExecutions;       // 0 = unlimited
        bool active;
        bytes32 budgetId;
    }

    /// @notice Signer delegation record.
    struct Delegation {
        address delegator;
        address delegate;
        uint256 validFrom;
        uint256 validUntil;
        bool active;
    }

    /// @notice Approved DeFi protocol for yield allocation.
    struct YieldProtocol {
        address protocolAddress;
        string name;
        uint256 maxAllocation;       // Maximum allocation in token units
        uint256 currentAllocation;
        bool active;
    }

    /// @notice Signer configuration.
    struct SignerConfig {
        uint256 totalSigners;
        uint256 smallThreshold;      // Approvals needed for small tx
        uint256 mediumThreshold;     // Approvals needed for medium tx
        uint256 largeThreshold;      // Approvals needed for large tx
        uint256 emergencyThreshold;  // Approvals needed for emergency tx
    }

    // ──────────────────────────────────────────────────────────────
    // Constants
    // ──────────────────────────────────────────────────────────────

    /// @notice Small transaction threshold ($10K in 6 decimals).
    uint256 public constant SMALL_TX_THRESHOLD = 10_000 * 1e6;

    /// @notice Large transaction threshold ($100K in 6 decimals).
    uint256 public constant LARGE_TX_THRESHOLD = 100_000 * 1e6;

    /// @notice Standard timelock for small/medium transactions (24 hours).
    uint256 public constant STANDARD_TIMELOCK = 24 hours;

    /// @notice Extended timelock for large transactions (48 hours).
    uint256 public constant LARGE_TIMELOCK = 48 hours;

    /// @notice Emergency timelock (1 hour).
    uint256 public constant EMERGENCY_TIMELOCK = 1 hours;

    /// @notice Proposal expiry (7 days).
    uint256 public constant PROPOSAL_EXPIRY = 7 days;

    /// @notice Signer rotation cooldown (48 hours).
    uint256 public constant SIGNER_COOLDOWN = 48 hours;

    /// @notice Maximum delegation period (30 days).
    uint256 public constant MAX_DELEGATION_PERIOD = 30 days;

    // ──────────────────────────────────────────────────────────────
    // State
    // ──────────────────────────────────────────────────────────────

    /// @notice Signer configuration.
    SignerConfig public signerConfig;

    /// @notice Proposal records keyed by proposal ID.
    mapping(bytes32 => Proposal) public proposals;

    /// @notice Per-proposal signer approval tracking.
    mapping(bytes32 => mapping(address => bool)) public proposalApprovals;

    /// @notice Per-proposal signer rejection tracking.
    mapping(bytes32 => mapping(address => bool)) public proposalRejections;

    /// @notice Budget records keyed by budget ID.
    mapping(bytes32 => Budget) public budgets;

    /// @notice Spending trackers keyed by budget ID.
    mapping(bytes32 => SpendingTracker) public spendingTrackers;

    /// @notice Active budget IDs.
    bytes32[] public activeBudgetIds;

    /// @notice Recurring payment records keyed by payment ID.
    mapping(bytes32 => RecurringPayment) public recurringPayments;

    /// @notice Active recurring payment IDs.
    bytes32[] public activeRecurringPaymentIds;

    /// @notice Delegation records keyed by delegator address.
    mapping(address => Delegation) public delegations;

    /// @notice Approved yield protocols keyed by protocol address.
    mapping(address => YieldProtocol) public yieldProtocols;

    /// @notice Supported tokens for treasury operations.
    mapping(address => bool) public supportedTokens;

    /// @notice List of all current signers.
    address[] public signers;

    /// @notice Index tracking for signers array.
    mapping(address => uint256) internal _signerIndex;

    /// @notice Signer last added timestamp (for cooldown).
    mapping(address => uint256) public signerAddedAt;

    /// @notice Proposal nonce.
    uint256 public proposalNonce;

    /// @notice Budget nonce.
    uint256 public budgetNonce;

    /// @notice Recurring payment nonce.
    uint256 public recurringNonce;

    /// @notice NoblePay core contract reference.
    address public noblePayContract;

    // ──────────────────────────────────────────────────────────────
    // Events
    // ──────────────────────────────────────────────────────────────

    event ProposalCreated(
        bytes32 indexed proposalId,
        address indexed proposer,
        address indexed recipient,
        uint256 amount,
        TxTier tier,
        bool isEmergency
    );

    event ProposalApproved(
        bytes32 indexed proposalId,
        address indexed signer,
        uint256 approvalCount,
        uint256 required
    );

    event ProposalRejected(
        bytes32 indexed proposalId,
        address indexed signer,
        uint256 rejectionCount
    );

    event ProposalExecuted(
        bytes32 indexed proposalId,
        address indexed executor,
        uint256 amount,
        uint256 executedAt
    );

    event ProposalCancelled(bytes32 indexed proposalId, address indexed cancelledBy);
    event ProposalExpired(bytes32 indexed proposalId);

    event BudgetCreated(
        bytes32 indexed budgetId,
        string name,
        SpendingCategory category,
        uint256 totalAllocation
    );

    event BudgetSpent(
        bytes32 indexed budgetId,
        uint256 amount,
        uint256 totalSpent,
        uint256 remaining
    );

    event RecurringPaymentCreated(
        bytes32 indexed paymentId,
        address indexed recipient,
        uint256 amount,
        PaymentFrequency frequency
    );

    event RecurringPaymentExecuted(
        bytes32 indexed paymentId,
        uint256 executionNumber,
        uint256 amount
    );

    event RecurringPaymentRevoked(bytes32 indexed paymentId);

    event SignerAdded(address indexed signer, uint256 totalSigners);
    event SignerRemoved(address indexed signer, uint256 totalSigners);
    event SignerConfigUpdated(uint256 small, uint256 medium, uint256 large, uint256 emergency);

    event DelegationCreated(
        address indexed delegator,
        address indexed delegate,
        uint256 validUntil
    );

    event DelegationRevoked(address indexed delegator, address indexed delegate);

    event YieldProtocolApproved(address indexed protocol, string name, uint256 maxAllocation);
    event YieldAllocated(address indexed protocol, uint256 amount);
    event YieldWithdrawn(address indexed protocol, uint256 amount);

    event TokenSupported(address indexed token, bool supported);
    event NoblePayUpdated(address indexed oldContract, address indexed newContract);

    // ──────────────────────────────────────────────────────────────
    // Errors
    // ──────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error UnsupportedToken();
    error ProposalNotFound();
    error InvalidProposalStatus(ProposalStatus current);
    error AlreadyApproved();
    error AlreadyRejected();
    error TimelockNotExpired(uint256 expiry, uint256 current);
    error ProposalExpiredError();
    error NotSigner();
    error SignerAlreadyExists();
    error CooldownActive(uint256 readyAt);
    error BudgetNotFound();
    error BudgetExceeded(uint256 requested, uint256 remaining);
    error DailyLimitExceeded(uint256 requested, uint256 remaining);
    error WeeklyLimitExceeded(uint256 requested, uint256 remaining);
    error MonthlyLimitExceeded(uint256 requested, uint256 remaining);
    error RecurringPaymentNotFound();
    error RecurringPaymentNotDue();
    error MaxExecutionsReached();
    error DelegationNotActive();
    error DelegationTooLong();
    error ProtocolNotApproved();
    error AllocationExceeded();
    error InsufficientBalance();
    error InvalidSignerConfig();
    error MinimumSignersRequired();

    // ──────────────────────────────────────────────────────────────
    // Modifiers
    // ──────────────────────────────────────────────────────────────

    /// @notice Restricts to signers or their active delegates.
    modifier onlySignerOrDelegate() {
        bool authorized = hasRole(SIGNER_ROLE, msg.sender);
        if (!authorized) {
            // Check if msg.sender is an active delegate for any signer
            Delegation storage del = delegations[msg.sender];
            authorized = del.active &&
                         del.delegate == msg.sender &&
                         block.timestamp >= del.validFrom &&
                         block.timestamp <= del.validUntil &&
                         hasRole(SIGNER_ROLE, del.delegator);
        }
        if (!authorized) revert NotSigner();
        _;
    }

    // ──────────────────────────────────────────────────────────────
    // Constructor
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Deploys MultiSigTreasury with initial signers and thresholds.
     * @param _admin             Admin address.
     * @param _initialSigners    Initial set of signers.
     * @param _smallThreshold    Approvals for small tx.
     * @param _mediumThreshold   Approvals for medium tx.
     * @param _largeThreshold    Approvals for large tx.
     * @param _emergencyThreshold Approvals for emergency tx.
     */
    constructor(
        address _admin,
        address[] memory _initialSigners,
        uint256 _smallThreshold,
        uint256 _mediumThreshold,
        uint256 _largeThreshold,
        uint256 _emergencyThreshold
    ) {
        if (_admin == address(0)) revert ZeroAddress();
        if (_initialSigners.length < 2) revert MinimumSignersRequired();
        if (
            _smallThreshold == 0 ||
            _smallThreshold > _mediumThreshold ||
            _mediumThreshold > _largeThreshold ||
            _largeThreshold > _initialSigners.length
        ) revert InvalidSignerConfig();

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);

        for (uint256 i; i < _initialSigners.length;) {
            if (_initialSigners[i] == address(0)) revert ZeroAddress();
            _grantRole(SIGNER_ROLE, _initialSigners[i]);
            _signerIndex[_initialSigners[i]] = signers.length;
            signers.push(_initialSigners[i]);
            signerAddedAt[_initialSigners[i]] = block.timestamp;

            unchecked { ++i; }
        }

        signerConfig = SignerConfig({
            totalSigners: _initialSigners.length,
            smallThreshold: _smallThreshold,
            mediumThreshold: _mediumThreshold,
            largeThreshold: _largeThreshold,
            emergencyThreshold: _emergencyThreshold
        });
    }

    // ──────────────────────────────────────────────────────────────
    // External — Proposal Lifecycle
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates a new treasury transfer proposal.
     * @param _recipient    Beneficiary address.
     * @param _token        ERC20 token address; address(0) for native.
     * @param _amount       Transfer amount.
     * @param _category     Spending category.
     * @param _description  Human-readable description.
     * @param _isEmergency  Whether this is an emergency fast-track proposal.
     * @param _budgetId     Associated budget ID (bytes32(0) if none).
     * @return proposalId   Unique proposal identifier.
     */
    function createProposal(
        address _recipient,
        address _token,
        uint256 _amount,
        SpendingCategory _category,
        string calldata _description,
        bool _isEmergency,
        bytes32 _budgetId
    ) external whenNotPaused onlySignerOrDelegate returns (bytes32 proposalId) {
        if (_recipient == address(0)) revert ZeroAddress();
        if (_amount == 0) revert ZeroAmount();
        if (_token != address(0) && !supportedTokens[_token]) revert UnsupportedToken();

        // Determine tier and requirements
        TxTier tier;
        uint256 requiredApprovals;
        uint256 timelock;

        if (_isEmergency) {
            tier = TxTier.EMERGENCY;
            requiredApprovals = signerConfig.emergencyThreshold;
            timelock = EMERGENCY_TIMELOCK;
        } else if (_amount <= SMALL_TX_THRESHOLD) {
            tier = TxTier.SMALL;
            requiredApprovals = signerConfig.smallThreshold;
            timelock = STANDARD_TIMELOCK;
        } else if (_amount <= LARGE_TX_THRESHOLD) {
            tier = TxTier.MEDIUM;
            requiredApprovals = signerConfig.mediumThreshold;
            timelock = STANDARD_TIMELOCK;
        } else {
            tier = TxTier.LARGE;
            requiredApprovals = signerConfig.largeThreshold;
            timelock = LARGE_TIMELOCK;
        }

        // Validate budget if specified
        if (_budgetId != bytes32(0)) {
            Budget storage budget = budgets[_budgetId];
            if (!budget.active) revert BudgetNotFound();
            uint256 remaining = budget.totalAllocation - budget.spent;
            if (_amount > remaining) revert BudgetExceeded(_amount, remaining);
        }

        proposalId = keccak256(
            abi.encodePacked(msg.sender, _recipient, _amount, block.timestamp, proposalNonce++)
        );

        // Resolve the canonical signer identity to prevent delegate double-counting
        address approver = _resolveApprover(msg.sender);

        proposals[proposalId] = Proposal({
            proposalId: proposalId,
            proposer: msg.sender,
            recipient: _recipient,
            token: _token,
            amount: _amount,
            category: _category,
            description: _description,
            tier: tier,
            status: ProposalStatus.PENDING,
            approvalCount: 1,
            rejectionCount: 0,
            requiredApprovals: requiredApprovals,
            createdAt: block.timestamp,
            timelockExpiry: block.timestamp + timelock,
            expiresAt: block.timestamp + PROPOSAL_EXPIRY,
            isEmergency: _isEmergency,
            budgetId: _budgetId
        });

        // Auto-approve by resolved approver identity
        proposalApprovals[proposalId][approver] = true;

        emit ProposalCreated(proposalId, msg.sender, _recipient, _amount, tier, _isEmergency);
        emit ProposalApproved(proposalId, msg.sender, 1, requiredApprovals);
    }

    /**
     * @notice Approves a pending proposal.
     * @param _proposalId Proposal to approve.
     */
    function approveProposal(
        bytes32 _proposalId
    ) external whenNotPaused onlySignerOrDelegate {
        Proposal storage p = proposals[_proposalId];
        if (p.createdAt == 0) revert ProposalNotFound();
        if (p.status != ProposalStatus.PENDING) revert InvalidProposalStatus(p.status);
        if (block.timestamp > p.expiresAt) revert ProposalExpiredError();

        // Resolve the canonical signer identity to prevent delegate double-counting
        address approver = _resolveApprover(msg.sender);
        if (proposalApprovals[_proposalId][approver]) revert AlreadyApproved();

        proposalApprovals[_proposalId][approver] = true;
        p.approvalCount++;

        if (p.approvalCount >= p.requiredApprovals) {
            p.status = ProposalStatus.APPROVED;
        }

        emit ProposalApproved(_proposalId, msg.sender, p.approvalCount, p.requiredApprovals);
    }

    /**
     * @notice Rejects a pending proposal.
     * @param _proposalId Proposal to reject.
     */
    function rejectProposal(
        bytes32 _proposalId
    ) external whenNotPaused onlySignerOrDelegate {
        Proposal storage p = proposals[_proposalId];
        if (p.createdAt == 0) revert ProposalNotFound();
        if (p.status != ProposalStatus.PENDING) revert InvalidProposalStatus(p.status);
        if (proposalRejections[_proposalId][msg.sender]) revert AlreadyRejected();

        proposalRejections[_proposalId][msg.sender] = true;
        p.rejectionCount++;

        // Auto-reject if majority rejects
        uint256 rejectThreshold = signerConfig.totalSigners - p.requiredApprovals + 1;
        if (p.rejectionCount >= rejectThreshold) {
            p.status = ProposalStatus.REJECTED;
        }

        emit ProposalRejected(_proposalId, msg.sender, p.rejectionCount);
    }

    /**
     * @notice Executes an approved proposal after timelock expiry.
     * @param _proposalId Proposal to execute.
     */
    function executeProposal(
        bytes32 _proposalId
    ) external whenNotPaused nonReentrant onlySignerOrDelegate {
        Proposal storage p = proposals[_proposalId];
        if (p.createdAt == 0) revert ProposalNotFound();
        if (p.status != ProposalStatus.APPROVED) revert InvalidProposalStatus(p.status);
        if (block.timestamp < p.timelockExpiry) {
            revert TimelockNotExpired(p.timelockExpiry, block.timestamp);
        }
        if (block.timestamp > p.expiresAt) revert ProposalExpiredError();

        p.status = ProposalStatus.EXECUTED;

        // Update budget if applicable
        if (p.budgetId != bytes32(0)) {
            _recordBudgetSpending(p.budgetId, p.amount);
        }

        // Execute transfer
        if (p.token == address(0)) {
            if (address(this).balance < p.amount) revert InsufficientBalance();
            (bool ok, ) = p.recipient.call{value: p.amount}("");
            require(ok, "MultiSigTreasury: native transfer failed");
        } else {
            if (IERC20(p.token).balanceOf(address(this)) < p.amount) revert InsufficientBalance();
            IERC20(p.token).safeTransfer(p.recipient, p.amount);
        }

        emit ProposalExecuted(_proposalId, msg.sender, p.amount, block.timestamp);
    }

    /**
     * @notice Cancels a pending or approved proposal.
     * @dev Only the original proposer or admin can cancel.
     * @param _proposalId Proposal to cancel.
     */
    function cancelProposal(bytes32 _proposalId) external whenNotPaused {
        Proposal storage p = proposals[_proposalId];
        if (p.createdAt == 0) revert ProposalNotFound();
        require(
            msg.sender == p.proposer || hasRole(ADMIN_ROLE, msg.sender),
            "MultiSigTreasury: not authorized to cancel"
        );
        require(
            p.status == ProposalStatus.PENDING || p.status == ProposalStatus.APPROVED,
            "MultiSigTreasury: cannot cancel"
        );

        p.status = ProposalStatus.CANCELLED;
        emit ProposalCancelled(_proposalId, msg.sender);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Budget Management
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates a budget allocation for a department or project.
     * @param _name           Budget name/label.
     * @param _category       Spending category.
     * @param _totalAllocation Total budget in token units.
     * @param _dailyLimit     Maximum daily spend.
     * @param _weeklyLimit    Maximum weekly spend.
     * @param _monthlyLimit   Maximum monthly spend.
     * @param _periodEnd      End of budget period.
     * @return budgetId       Unique budget identifier.
     */
    function createBudget(
        string calldata _name,
        SpendingCategory _category,
        uint256 _totalAllocation,
        uint256 _dailyLimit,
        uint256 _weeklyLimit,
        uint256 _monthlyLimit,
        uint256 _periodEnd
    ) external onlyRole(BUDGET_MANAGER_ROLE) whenNotPaused returns (bytes32 budgetId) {
        if (_totalAllocation == 0) revert ZeroAmount();
        require(_periodEnd > block.timestamp, "MultiSigTreasury: invalid period");

        budgetId = keccak256(
            abi.encodePacked(_name, _category, block.timestamp, budgetNonce++)
        );

        budgets[budgetId] = Budget({
            budgetId: budgetId,
            name: _name,
            category: _category,
            totalAllocation: _totalAllocation,
            spent: 0,
            dailyLimit: _dailyLimit,
            weeklyLimit: _weeklyLimit,
            monthlyLimit: _monthlyLimit,
            createdAt: block.timestamp,
            periodStart: block.timestamp,
            periodEnd: _periodEnd,
            active: true
        });

        spendingTrackers[budgetId] = SpendingTracker({
            dailySpent: 0,
            weeklySpent: 0,
            monthlySpent: 0,
            lastDayReset: block.timestamp,
            lastWeekReset: block.timestamp,
            lastMonthReset: block.timestamp
        });

        activeBudgetIds.push(budgetId);

        emit BudgetCreated(budgetId, _name, _category, _totalAllocation);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Recurring Payments
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates a recurring payment authorization (standing order).
     * @param _recipient      Payment recipient.
     * @param _token          ERC20 token; address(0) for native.
     * @param _amount         Payment amount per execution.
     * @param _frequency      Payment frequency.
     * @param _category       Spending category.
     * @param _description    Payment description.
     * @param _maxExecutions  Maximum number of executions (0 = unlimited).
     * @param _budgetId       Associated budget ID.
     * @return paymentId      Unique payment identifier.
     */
    function createRecurringPayment(
        address _recipient,
        address _token,
        uint256 _amount,
        PaymentFrequency _frequency,
        SpendingCategory _category,
        string calldata _description,
        uint256 _maxExecutions,
        bytes32 _budgetId
    ) external whenNotPaused onlyRole(ADMIN_ROLE) returns (bytes32 paymentId) {
        if (_recipient == address(0)) revert ZeroAddress();
        if (_amount == 0) revert ZeroAmount();

        uint256 nextExec = block.timestamp + _frequencyToSeconds(_frequency);

        paymentId = keccak256(
            abi.encodePacked(msg.sender, _recipient, _amount, block.timestamp, recurringNonce++)
        );

        recurringPayments[paymentId] = RecurringPayment({
            paymentId: paymentId,
            recipient: _recipient,
            token: _token,
            amount: _amount,
            frequency: _frequency,
            category: _category,
            description: _description,
            nextExecution: nextExec,
            lastExecuted: 0,
            executionCount: 0,
            maxExecutions: _maxExecutions,
            active: true,
            budgetId: _budgetId
        });

        activeRecurringPaymentIds.push(paymentId);

        emit RecurringPaymentCreated(paymentId, _recipient, _amount, _frequency);
    }

    /**
     * @notice Executes a due recurring payment.
     * @param _paymentId Recurring payment to execute.
     */
    function executeRecurringPayment(
        bytes32 _paymentId
    ) external whenNotPaused nonReentrant {
        RecurringPayment storage rp = recurringPayments[_paymentId];
        if (!rp.active) revert RecurringPaymentNotFound();
        if (block.timestamp < rp.nextExecution) revert RecurringPaymentNotDue();
        if (rp.maxExecutions > 0 && rp.executionCount >= rp.maxExecutions) {
            revert MaxExecutionsReached();
        }

        rp.executionCount++;
        rp.lastExecuted = block.timestamp;
        rp.nextExecution = block.timestamp + _frequencyToSeconds(rp.frequency);

        // Update budget if applicable
        if (rp.budgetId != bytes32(0)) {
            _recordBudgetSpending(rp.budgetId, rp.amount);
        }

        // Execute transfer
        if (rp.token == address(0)) {
            if (address(this).balance < rp.amount) revert InsufficientBalance();
            (bool ok, ) = rp.recipient.call{value: rp.amount}("");
            require(ok, "MultiSigTreasury: recurring payment failed");
        } else {
            IERC20(rp.token).safeTransfer(rp.recipient, rp.amount);
        }

        emit RecurringPaymentExecuted(_paymentId, rp.executionCount, rp.amount);
    }

    /**
     * @notice Revokes a recurring payment authorization.
     * @param _paymentId Payment to revoke.
     */
    function revokeRecurringPayment(
        bytes32 _paymentId
    ) external whenNotPaused onlySignerOrDelegate {
        RecurringPayment storage rp = recurringPayments[_paymentId];
        if (!rp.active) revert RecurringPaymentNotFound();

        rp.active = false;
        emit RecurringPaymentRevoked(_paymentId);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Delegation
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Delegates signing authority to another address temporarily.
     * @param _delegate  Address to delegate to.
     * @param _duration  Duration in seconds (max 30 days).
     */
    function delegateSigningAuthority(
        address _delegate,
        uint256 _duration
    ) external onlyRole(SIGNER_ROLE) whenNotPaused {
        if (_delegate == address(0)) revert ZeroAddress();
        if (_duration > MAX_DELEGATION_PERIOD) revert DelegationTooLong();

        delegations[_delegate] = Delegation({
            delegator: msg.sender,
            delegate: _delegate,
            validFrom: block.timestamp,
            validUntil: block.timestamp + _duration,
            active: true
        });

        emit DelegationCreated(msg.sender, _delegate, block.timestamp + _duration);
    }

    /**
     * @notice Revokes a delegation.
     * @param _delegate Address whose delegation to revoke.
     */
    function revokeDelegation(address _delegate) external onlyRole(SIGNER_ROLE) {
        Delegation storage del = delegations[_delegate];
        require(del.delegator == msg.sender, "MultiSigTreasury: not delegator");

        del.active = false;
        emit DelegationRevoked(msg.sender, _delegate);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Yield Management
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Approves a DeFi protocol for yield allocation.
     * @param _protocol      Protocol contract address.
     * @param _name          Protocol name.
     * @param _maxAllocation Maximum allocation allowed.
     */
    function approveYieldProtocol(
        address _protocol,
        string calldata _name,
        uint256 _maxAllocation
    ) external onlyRole(ADMIN_ROLE) {
        if (_protocol == address(0)) revert ZeroAddress();

        yieldProtocols[_protocol] = YieldProtocol({
            protocolAddress: _protocol,
            name: _name,
            maxAllocation: _maxAllocation,
            currentAllocation: 0,
            active: true
        });

        emit YieldProtocolApproved(_protocol, _name, _maxAllocation);
    }

    /**
     * @notice Allocates treasury funds to an approved yield protocol.
     * @param _protocol Protocol address to allocate to.
     * @param _token    Token to allocate.
     * @param _amount   Amount to allocate.
     */
    function allocateToYield(
        address _protocol,
        address _token,
        uint256 _amount
    ) external whenNotPaused nonReentrant onlyRole(YIELD_MANAGER_ROLE) {
        YieldProtocol storage yp = yieldProtocols[_protocol];
        if (!yp.active) revert ProtocolNotApproved();
        if (_amount == 0) revert ZeroAmount();
        if (yp.currentAllocation + _amount > yp.maxAllocation) revert AllocationExceeded();

        yp.currentAllocation += _amount;

        IERC20(_token).safeTransfer(_protocol, _amount);

        emit YieldAllocated(_protocol, _amount);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Signer Management
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Adds a new signer with cooldown.
     * @param _signer Address to add as signer.
     */
    function addSigner(address _signer) external onlyRole(ADMIN_ROLE) {
        if (_signer == address(0)) revert ZeroAddress();
        if (hasRole(SIGNER_ROLE, _signer)) revert SignerAlreadyExists();

        _grantRole(SIGNER_ROLE, _signer);
        _signerIndex[_signer] = signers.length;
        signers.push(_signer);
        signerAddedAt[_signer] = block.timestamp;
        signerConfig.totalSigners++;

        emit SignerAdded(_signer, signerConfig.totalSigners);
    }

    /**
     * @notice Removes a signer (subject to cooldown and minimum threshold).
     * @param _signer Address to remove.
     */
    function removeSigner(address _signer) external onlyRole(ADMIN_ROLE) {
        if (!hasRole(SIGNER_ROLE, _signer)) revert NotSigner();
        if (signerConfig.totalSigners <= signerConfig.largeThreshold) {
            revert MinimumSignersRequired();
        }

        _revokeRole(SIGNER_ROLE, _signer);

        // Swap-and-pop removal
        uint256 index = _signerIndex[_signer];
        uint256 lastIndex = signers.length - 1;
        if (index != lastIndex) {
            address lastSigner = signers[lastIndex];
            signers[index] = lastSigner;
            _signerIndex[lastSigner] = index;
        }
        signers.pop();
        delete _signerIndex[_signer];
        signerConfig.totalSigners--;

        emit SignerRemoved(_signer, signerConfig.totalSigners);
    }

    /**
     * @notice Updates approval thresholds.
     * @param _small     New small tx threshold.
     * @param _medium    New medium tx threshold.
     * @param _large     New large tx threshold.
     * @param _emergency New emergency threshold.
     */
    function updateSignerConfig(
        uint256 _small,
        uint256 _medium,
        uint256 _large,
        uint256 _emergency
    ) external onlyRole(ADMIN_ROLE) {
        if (
            _small == 0 ||
            _small > _medium ||
            _medium > _large ||
            _large > signerConfig.totalSigners
        ) revert InvalidSignerConfig();

        signerConfig.smallThreshold = _small;
        signerConfig.mediumThreshold = _medium;
        signerConfig.largeThreshold = _large;
        signerConfig.emergencyThreshold = _emergency;

        emit SignerConfigUpdated(_small, _medium, _large, _emergency);
    }

    // ──────────────────────────────────────────────────────────────
    // View Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Returns a proposal record.
    function getProposal(bytes32 _proposalId) external view returns (Proposal memory) {
        return proposals[_proposalId];
    }

    /// @notice Returns a budget record.
    function getBudget(bytes32 _budgetId) external view returns (Budget memory) {
        return budgets[_budgetId];
    }

    /// @notice Returns the spending tracker for a budget.
    function getSpendingTracker(bytes32 _budgetId) external view returns (SpendingTracker memory) {
        return spendingTrackers[_budgetId];
    }

    /// @notice Returns a recurring payment record.
    function getRecurringPayment(bytes32 _paymentId) external view returns (RecurringPayment memory) {
        return recurringPayments[_paymentId];
    }

    /// @notice Returns the current signer list.
    function getSigners() external view returns (address[] memory) {
        return signers;
    }

    /// @notice Returns the current signer configuration.
    function getSignerConfig() external view returns (SignerConfig memory) {
        return signerConfig;
    }

    /// @notice Checks if a signer has approved a specific proposal.
    function hasApproved(bytes32 _proposalId, address _signer) external view returns (bool) {
        return proposalApprovals[_proposalId][_signer];
    }

    /// @notice Returns the active budget IDs.
    function getActiveBudgets() external view returns (bytes32[] memory) {
        return activeBudgetIds;
    }

    // ──────────────────────────────────────────────────────────────
    // Admin Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Adds or removes a supported token.
    function setSupportedToken(address _token, bool _supported) external onlyRole(ADMIN_ROLE) {
        if (_token == address(0)) revert ZeroAddress();
        supportedTokens[_token] = _supported;
        emit TokenSupported(_token, _supported);
    }

    /// @notice Sets the NoblePay contract reference.
    function setNoblePayContract(address _noblepay) external onlyRole(ADMIN_ROLE) {
        if (_noblepay == address(0)) revert ZeroAddress();
        address old = noblePayContract;
        noblePayContract = _noblepay;
        emit NoblePayUpdated(old, _noblepay);
    }

    /// @notice Emergency pause.
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /// @notice Resume operations.
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ──────────────────────────────────────────────────────────────
    // Internal Helpers
    // ──────────────────────────────────────────────────────────────

    /**
     * @dev Resolves the effective approver identity. If `caller` is an active
     *      delegate, returns the delegator (the underlying signer). Otherwise
     *      returns `caller` itself. This prevents a signer from getting two
     *      votes by approving once directly and once through their delegate.
     * @param caller The msg.sender to resolve.
     * @return The canonical signer address for approval tracking.
     */
    function _resolveApprover(address caller) internal view returns (address) {
        if (hasRole(SIGNER_ROLE, caller)) {
            return caller;
        }
        // caller must be a delegate (onlySignerOrDelegate already validated)
        Delegation storage del = delegations[caller];
        return del.delegator;
    }

    /**
     * @dev Records spending against a budget with limit enforcement.
     * @param _budgetId Budget to charge.
     * @param _amount   Amount being spent.
     */
    function _recordBudgetSpending(bytes32 _budgetId, uint256 _amount) internal {
        Budget storage budget = budgets[_budgetId];
        if (!budget.active) revert BudgetNotFound();

        uint256 remaining = budget.totalAllocation - budget.spent;
        if (_amount > remaining) revert BudgetExceeded(_amount, remaining);

        SpendingTracker storage tracker = spendingTrackers[_budgetId];

        // Reset daily tracker if new day
        if (block.timestamp / 1 days > tracker.lastDayReset / 1 days) {
            tracker.dailySpent = 0;
            tracker.lastDayReset = block.timestamp;
        }

        // Reset weekly tracker if new week
        if (block.timestamp / 7 days > tracker.lastWeekReset / 7 days) {
            tracker.weeklySpent = 0;
            tracker.lastWeekReset = block.timestamp;
        }

        // Reset monthly tracker if new month
        if (block.timestamp / 30 days > tracker.lastMonthReset / 30 days) {
            tracker.monthlySpent = 0;
            tracker.lastMonthReset = block.timestamp;
        }

        // Enforce limits
        if (budget.dailyLimit > 0) {
            uint256 dailyRemaining = budget.dailyLimit - tracker.dailySpent;
            if (_amount > dailyRemaining) revert DailyLimitExceeded(_amount, dailyRemaining);
        }
        if (budget.weeklyLimit > 0) {
            uint256 weeklyRemaining = budget.weeklyLimit - tracker.weeklySpent;
            if (_amount > weeklyRemaining) revert WeeklyLimitExceeded(_amount, weeklyRemaining);
        }
        if (budget.monthlyLimit > 0) {
            uint256 monthlyRemaining = budget.monthlyLimit - tracker.monthlySpent;
            if (_amount > monthlyRemaining) revert MonthlyLimitExceeded(_amount, monthlyRemaining);
        }

        budget.spent += _amount;
        tracker.dailySpent += _amount;
        tracker.weeklySpent += _amount;
        tracker.monthlySpent += _amount;

        emit BudgetSpent(_budgetId, _amount, budget.spent, budget.totalAllocation - budget.spent);
    }

    /**
     * @dev Converts a payment frequency enum to seconds.
     * @param _frequency Payment frequency.
     * @return Number of seconds between payments.
     */
    function _frequencyToSeconds(PaymentFrequency _frequency) internal pure returns (uint256) {
        if (_frequency == PaymentFrequency.DAILY) return 1 days;
        if (_frequency == PaymentFrequency.WEEKLY) return 7 days;
        if (_frequency == PaymentFrequency.BIWEEKLY) return 14 days;
        if (_frequency == PaymentFrequency.MONTHLY) return 30 days;
        if (_frequency == PaymentFrequency.QUARTERLY) return 90 days;
        return 30 days; // Default to monthly
    }

    /// @notice Allows the contract to receive native tokens.
    receive() external payable {}
}

src/PaymentChannels.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title PaymentChannels
 * @author Aethelred Team
 * @notice High-frequency settlement channel contract for the NoblePay cross-border
 *         payment platform. Enables bi-directional payment channels for high-volume
 *         B2B payments with off-chain signing and on-chain settlement, dispute
 *         resolution, multi-hop routing, and HTLC conditional payments.
 *
 * @dev Architecture overview:
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │                     PAYMENT CHANNELS                              │
 * ├───────────────────────────────────────────────────────────────────┤
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Channel Mgmt    │  │  Settlement       │  │  Disputes      │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • open          │  │  • cooperative     │  │  • challenge   │  │
 * │  │  • fund          │  │  • unilateral      │  │  • respond     │  │
 * │  │  • close         │  │  • off-chain sign  │  │  • timeout     │  │
 * │  │  • batch ops     │  │  • on-chain final  │  │  • slash       │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Routing          │  │  HTLC             │  │  Watchtowers   │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • multi-hop     │  │  • hash locks     │  │  • register    │  │
 * │  │  • intermediary  │  │  • time locks     │  │  • monitor     │  │
 * │  │  • fees          │  │  • conditional     │  │  • bounty      │  │
 * │  │  • path finding  │  │  • atomic swap     │  │  • alert       │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * Channel lifecycle:
 *   OPEN -> FUNDED -> ACTIVE -> (DISPUTE_PERIOD ->) CLOSED
 *
 * Off-chain payment protocol:
 *   1. Parties exchange signed state updates off-chain
 *   2. Each state has a monotonically increasing nonce
 *   3. Either party can submit the latest state to close cooperatively
 *   4. Disputes use the challenge-response pattern with timeouts
 *   5. HTLCs enable conditional multi-hop payments
 */
contract PaymentChannels is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    // ──────────────────────────────────────────────────────────────
    // Roles
    // ──────────────────────────────────────────────────────────────

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant ROUTER_ROLE = keccak256("ROUTER_ROLE");
    bytes32 public constant WATCHTOWER_ROLE = keccak256("WATCHTOWER_ROLE");

    // ──────────────────────────────────────────────────────────────
    // Enums
    // ──────────────────────────────────────────────────────────────

    /// @notice Lifecycle status of a payment channel.
    enum ChannelStatus {
        OPEN,
        FUNDED,
        ACTIVE,
        CLOSING,
        DISPUTE,
        CLOSED
    }

    /// @notice Status of an HTLC (Hash Time-Locked Contract).
    enum HTLCStatus {
        ACTIVE,
        CLAIMED,
        REFUNDED,
        EXPIRED
    }

    // ──────────────────────────────────────────────────────────────
    // Structs
    // ──────────────────────────────────────────────────────────────

    /// @notice Bi-directional payment channel between two parties.
    struct Channel {
        bytes32 channelId;
        address partyA;              // Channel opener
        address partyB;              // Channel counterparty
        address token;               // ERC20 settlement token
        uint256 depositA;            // Party A's total deposit
        uint256 depositB;            // Party B's total deposit
        uint256 balanceA;            // Party A's current balance
        uint256 balanceB;            // Party B's current balance
        ChannelStatus status;
        uint256 nonce;               // Latest agreed state nonce
        uint256 openedAt;
        uint256 closingAt;           // When closing was initiated
        uint256 closedAt;
        uint256 challengePeriod;     // Duration of dispute window
        uint256 routingFeeBps;       // Fee charged if used as routing hop
    }

    /// @notice Dispute record for a channel.
    struct ChannelDispute {
        bytes32 channelId;
        address challenger;          // Party that initiated the dispute
        uint256 challengeNonce;      // State nonce submitted by challenger
        uint256 challengeBalanceA;   // Challenger's claimed balance A
        uint256 challengeBalanceB;   // Challenger's claimed balance B
        uint256 initiatedAt;
        uint256 expiresAt;           // Deadline for counter-challenge
        bool resolved;
    }

    /// @notice Hash Time-Locked Contract for conditional payments.
    struct HTLC {
        bytes32 htlcId;
        bytes32 channelId;
        address sender;
        address receiver;
        uint256 amount;
        bytes32 hashLock;            // keccak256(preimage)
        uint256 timelock;            // Expiry timestamp
        HTLCStatus status;
        uint256 createdAt;
    }

    /// @notice Registered watchtower for channel monitoring.
    struct Watchtower {
        address operator;
        uint256 stake;               // Staked collateral
        uint256 bountyBps;           // Bounty rate in basis points
        uint256 channelsMonitored;
        uint256 disputesRaised;
        bool active;
        uint256 registeredAt;
    }

    /// @notice Multi-hop routing path record.
    struct RoutingPath {
        bytes32 pathId;
        bytes32[] channelIds;        // Ordered list of channels in the path
        address[] intermediaries;    // Routing nodes
        uint256 totalFees;           // Sum of routing fees
        uint256 amount;              // Payment amount
        uint256 createdAt;
        bool completed;
    }

    // ──────────────────────────────────────────────────────────────
    // Constants
    // ──────────────────────────────────────────────────────────────

    /// @notice Default challenge period for disputes (24 hours).
    uint256 public constant DEFAULT_CHALLENGE_PERIOD = 24 hours;

    /// @notice Minimum challenge period (1 hour).
    uint256 public constant MIN_CHALLENGE_PERIOD = 1 hours;

    /// @notice Maximum challenge period (7 days).
    uint256 public constant MAX_CHALLENGE_PERIOD = 7 days;

    /// @notice Minimum HTLC timelock (1 hour).
    uint256 public constant MIN_HTLC_TIMELOCK = 1 hours;

    /// @notice Maximum HTLC timelock (30 days).
    uint256 public constant MAX_HTLC_TIMELOCK = 30 days;

    /// @notice Maximum routing fee in basis points (5%).
    uint256 public constant MAX_ROUTING_FEE_BPS = 500;

    /// @notice Maximum hops in a routing path.
    uint256 public constant MAX_ROUTING_HOPS = 5;

    /// @notice Minimum watchtower stake.
    uint256 public constant MIN_WATCHTOWER_STAKE = 1 ether;

    /// @notice Maximum batch operation size.
    uint256 public constant MAX_BATCH_SIZE = 20;

    // ──────────────────────────────────────────────────────────────
    // State
    // ──────────────────────────────────────────────────────────────

    /// @notice Channel records keyed by channel ID.
    mapping(bytes32 => Channel) public channels;

    /// @notice Dispute records keyed by channel ID.
    mapping(bytes32 => ChannelDispute) public disputes;

    /// @notice HTLC records keyed by HTLC ID.
    mapping(bytes32 => HTLC) public htlcs;

    /// @notice Active HTLCs per channel.
    mapping(bytes32 => bytes32[]) public channelHTLCs;

    /// @notice Watchtower records keyed by operator address.
    mapping(address => Watchtower) public watchtowers;

    /// @notice Watchtower assignments: channelId => watchtower addresses.
    mapping(bytes32 => address[]) public channelWatchtowers;

    /// @notice Routing path records keyed by path ID.
    mapping(bytes32 => RoutingPath) public routingPaths;

    /// @notice Channels per address (for both parties).
    mapping(address => bytes32[]) public userChannels;

    /// @notice Supported settlement tokens.
    mapping(address => bool) public supportedTokens;

    /// @notice KYC-verified parties (integration with NoblePay compliance).
    mapping(address => bool) public kycVerified;

    /// @notice Channel nonce for unique ID generation.
    uint256 public channelNonce;

    /// @notice HTLC nonce.
    uint256 public htlcNonce;

    /// @notice Routing path nonce.
    uint256 public routingNonce;

    /// @notice Protocol fee on channel closings in basis points.
    uint256 public protocolFeeBps;

    /// @notice Protocol treasury.
    address public protocolTreasury;

    /// @notice NoblePay core contract reference.
    address public noblePayContract;

    // ──────────────────────────────────────────────────────────────
    // Events
    // ──────────────────────────────────────────────────────────────

    event ChannelOpened(
        bytes32 indexed channelId,
        address indexed partyA,
        address indexed partyB,
        address token,
        uint256 depositA,
        uint256 challengePeriod
    );

    event ChannelFunded(
        bytes32 indexed channelId,
        address indexed funder,
        uint256 amount,
        uint256 totalDeposit
    );

    event ChannelActivated(bytes32 indexed channelId);

    event ChannelCooperativeClose(
        bytes32 indexed channelId,
        uint256 finalBalanceA,
        uint256 finalBalanceB,
        uint256 nonce
    );

    event ChannelUnilateralClose(
        bytes32 indexed channelId,
        address indexed initiator,
        uint256 claimedBalanceA,
        uint256 claimedBalanceB,
        uint256 nonce
    );

    event ChannelClosed(
        bytes32 indexed channelId,
        uint256 finalBalanceA,
        uint256 finalBalanceB
    );

    event DisputeInitiated(
        bytes32 indexed channelId,
        address indexed challenger,
        uint256 nonce,
        uint256 expiresAt
    );

    event DisputeCountered(
        bytes32 indexed channelId,
        address indexed responder,
        uint256 higherNonce
    );

    event DisputeResolved(
        bytes32 indexed channelId,
        uint256 finalBalanceA,
        uint256 finalBalanceB
    );

    event HTLCCreated(
        bytes32 indexed htlcId,
        bytes32 indexed channelId,
        address indexed sender,
        uint256 amount,
        bytes32 hashLock,
        uint256 timelock
    );

    event HTLCClaimed(
        bytes32 indexed htlcId,
        bytes32 preimage
    );

    event HTLCRefunded(bytes32 indexed htlcId);

    event WatchtowerRegistered(
        address indexed operator,
        uint256 stake,
        uint256 bountyBps
    );

    event WatchtowerDeregistered(address indexed operator, uint256 stakeReturned);

    event WatchtowerAssigned(
        bytes32 indexed channelId,
        address indexed watchtower
    );

    event RoutingPathCreated(
        bytes32 indexed pathId,
        uint256 hops,
        uint256 amount,
        uint256 totalFees
    );

    event RoutingPathCompleted(bytes32 indexed pathId);

    event ChannelBatchOpened(uint256 count);
    event KYCStatusUpdated(address indexed party, bool verified);
    event TokenSupported(address indexed token, bool supported);

    // ──────────────────────────────────────────────────────────────
    // Errors
    // ──────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error UnsupportedToken();
    error ChannelNotFound();
    error InvalidChannelStatus(ChannelStatus current);
    error NotChannelParty();
    error InsufficientDeposit();
    error InvalidSignature();
    error NonceTooLow(uint256 provided, uint256 current);
    error ChallengePeriodActive();
    error ChallengePeriodExpired();
    error ChallengeNotExpired();
    error InvalidChallengePeriod();
    error HTLCNotFound();
    error HTLCExpired();
    error HTLCNotExpired();
    error InvalidPreimage();
    error InvalidHTLCStatus(HTLCStatus current);
    error InvalidTimelock();
    error WatchtowerNotFound();
    error WatchtowerAlreadyRegistered();
    error InsufficientStake();
    error RoutingPathTooLong();
    error KYCRequired();
    error InvalidBalances();
    error BatchTooLarge();
    error ChannelAlreadyExists();
    error InvalidFee();

    // ──────────────────────────────────────────────────────────────
    // Modifiers
    // ──────────────────────────────────────────────────────────────

    /// @notice Requires both parties to be KYC-verified.
    modifier onlyKYCVerified(address _partyA, address _partyB) {
        if (!kycVerified[_partyA]) revert KYCRequired();
        if (!kycVerified[_partyB]) revert KYCRequired();
        _;
    }

    /// @notice Restricts to channel participants.
    modifier onlyChannelParty(bytes32 _channelId) {
        Channel storage ch = channels[_channelId];
        if (msg.sender != ch.partyA && msg.sender != ch.partyB) revert NotChannelParty();
        _;
    }

    // ──────────────────────────────────────────────────────────────
    // Constructor
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Deploys PaymentChannels.
     * @param _admin           Admin address.
     * @param _protocolTreasury Treasury for protocol fees.
     * @param _protocolFeeBps  Protocol fee in basis points.
     */
    constructor(
        address _admin,
        address _protocolTreasury,
        uint256 _protocolFeeBps
    ) {
        if (_admin == address(0)) revert ZeroAddress();
        if (_protocolTreasury == address(0)) revert ZeroAddress();
        if (_protocolFeeBps > 500) revert InvalidFee();

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);

        protocolTreasury = _protocolTreasury;
        protocolFeeBps = _protocolFeeBps;
    }

    // ──────────────────────────────────────────────────────────────
    // External — Channel Lifecycle
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Opens a new bi-directional payment channel.
     * @param _partyB          Counterparty address.
     * @param _token           ERC20 settlement token.
     * @param _depositAmount   Initial deposit from party A.
     * @param _challengePeriod Dispute challenge window in seconds.
     * @param _routingFeeBps   Fee for routing through this channel.
     * @return channelId       Unique channel identifier.
     */
    function openChannel(
        address _partyB,
        address _token,
        uint256 _depositAmount,
        uint256 _challengePeriod,
        uint256 _routingFeeBps
    ) external whenNotPaused nonReentrant onlyKYCVerified(msg.sender, _partyB) returns (bytes32 channelId) {
        if (_partyB == address(0) || _partyB == msg.sender) revert ZeroAddress();
        if (!supportedTokens[_token]) revert UnsupportedToken();
        if (_depositAmount == 0) revert ZeroAmount();
        _validateChannelParams(_challengePeriod, _routingFeeBps);

        channelId = keccak256(
            abi.encodePacked(msg.sender, _partyB, _token, block.timestamp, channelNonce++)
        );

        channels[channelId] = Channel({
            channelId: channelId,
            partyA: msg.sender,
            partyB: _partyB,
            token: _token,
            depositA: _depositAmount,
            depositB: 0,
            balanceA: _depositAmount,
            balanceB: 0,
            status: ChannelStatus.OPEN,
            nonce: 0,
            openedAt: block.timestamp,
            closingAt: 0,
            closedAt: 0,
            challengePeriod: _challengePeriod,
            routingFeeBps: _routingFeeBps
        });

        userChannels[msg.sender].push(channelId);
        userChannels[_partyB].push(channelId);

        IERC20(_token).safeTransferFrom(msg.sender, address(this), _depositAmount);

        emit ChannelOpened(channelId, msg.sender, _partyB, _token, _depositAmount, _challengePeriod);
    }

    /**
     * @notice Funds a channel (counterparty deposit or top-up).
     * @param _channelId Channel to fund.
     * @param _amount    Amount to deposit.
     */
    function fundChannel(
        bytes32 _channelId,
        uint256 _amount
    ) external whenNotPaused nonReentrant onlyChannelParty(_channelId) {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.OPEN && ch.status != ChannelStatus.FUNDED && ch.status != ChannelStatus.ACTIVE) {
            revert InvalidChannelStatus(ch.status);
        }
        if (_amount == 0) revert ZeroAmount();

        if (msg.sender == ch.partyA) {
            ch.depositA += _amount;
            ch.balanceA += _amount;
        } else {
            ch.depositB += _amount;
            ch.balanceB += _amount;
        }

        // Activate if both parties have funded
        if (ch.status == ChannelStatus.OPEN && ch.depositB > 0) {
            ch.status = ChannelStatus.FUNDED;
            emit ChannelActivated(_channelId);
        }

        if (ch.status == ChannelStatus.FUNDED) {
            ch.status = ChannelStatus.ACTIVE;
        }

        IERC20(ch.token).safeTransferFrom(msg.sender, address(this), _amount);

        uint256 totalDeposit = msg.sender == ch.partyA ? ch.depositA : ch.depositB;
        emit ChannelFunded(_channelId, msg.sender, _amount, totalDeposit);
    }

    /**
     * @notice Cooperatively closes a channel with both parties' signatures.
     * @dev Both parties sign the final state off-chain. Either party submits
     *      it on-chain for immediate settlement (no challenge period).
     * @param _channelId    Channel to close.
     * @param _finalBalanceA Agreed final balance for party A.
     * @param _finalBalanceB Agreed final balance for party B.
     * @param _nonce         State nonce (must be higher than current).
     * @param _signatureA    Party A's signature of the final state.
     * @param _signatureB    Party B's signature of the final state.
     */
    function cooperativeClose(
        bytes32 _channelId,
        uint256 _finalBalanceA,
        uint256 _finalBalanceB,
        uint256 _nonce,
        bytes calldata _signatureA,
        bytes calldata _signatureB
    ) external whenNotPaused nonReentrant onlyChannelParty(_channelId) {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.ACTIVE && ch.status != ChannelStatus.FUNDED) {
            revert InvalidChannelStatus(ch.status);
        }
        if (_nonce <= ch.nonce) revert NonceTooLow(_nonce, ch.nonce);

        uint256 totalDeposit = ch.depositA + ch.depositB;
        if (_finalBalanceA + _finalBalanceB != totalDeposit) revert InvalidBalances();

        // Verify both signatures
        bytes32 stateHash = keccak256(
            abi.encodePacked(_channelId, _finalBalanceA, _finalBalanceB, _nonce, "CLOSE")
        );
        bytes32 ethSignedHash = stateHash.toEthSignedMessageHash();

        address signerA = ethSignedHash.recover(_signatureA);
        address signerB = ethSignedHash.recover(_signatureB);

        if (signerA != ch.partyA) revert InvalidSignature();
        if (signerB != ch.partyB) revert InvalidSignature();

        _settleChannel(ch, _finalBalanceA, _finalBalanceB, _nonce);

        emit ChannelCooperativeClose(_channelId, _finalBalanceA, _finalBalanceB, _nonce);
    }

    /**
     * @notice Initiates a unilateral close with the latest known state.
     * @dev Starts the challenge period. The counterparty can dispute with
     *      a higher-nonce state during the challenge window.
     * @param _channelId    Channel to close.
     * @param _balanceA     Claimed balance for party A.
     * @param _balanceB     Claimed balance for party B.
     * @param _nonce        State nonce.
     * @param _signature    Counterparty's signature of this state.
     */
    function initiateUnilateralClose(
        bytes32 _channelId,
        uint256 _balanceA,
        uint256 _balanceB,
        uint256 _nonce,
        bytes calldata _signature
    ) external whenNotPaused onlyChannelParty(_channelId) {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.ACTIVE && ch.status != ChannelStatus.FUNDED) {
            revert InvalidChannelStatus(ch.status);
        }
        if (_nonce <= ch.nonce) revert NonceTooLow(_nonce, ch.nonce);

        uint256 totalDeposit = ch.depositA + ch.depositB;
        if (_balanceA + _balanceB != totalDeposit) revert InvalidBalances();

        // Verify counterparty's signature
        bytes32 stateHash = keccak256(
            abi.encodePacked(_channelId, _balanceA, _balanceB, _nonce, "STATE")
        );
        bytes32 ethSignedHash = stateHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(_signature);

        address counterparty = msg.sender == ch.partyA ? ch.partyB : ch.partyA;
        if (signer != counterparty) revert InvalidSignature();

        ch.status = ChannelStatus.CLOSING;
        ch.closingAt = block.timestamp;
        ch.balanceA = _balanceA;
        ch.balanceB = _balanceB;
        ch.nonce = _nonce;

        // Create dispute record
        disputes[_channelId] = ChannelDispute({
            channelId: _channelId,
            challenger: msg.sender,
            challengeNonce: _nonce,
            challengeBalanceA: _balanceA,
            challengeBalanceB: _balanceB,
            initiatedAt: block.timestamp,
            expiresAt: block.timestamp + ch.challengePeriod,
            resolved: false
        });

        emit ChannelUnilateralClose(_channelId, msg.sender, _balanceA, _balanceB, _nonce);
        emit DisputeInitiated(_channelId, msg.sender, _nonce, block.timestamp + ch.challengePeriod);
    }

    /**
     * @notice Counters a unilateral close with a higher-nonce state.
     * @param _channelId    Channel being disputed.
     * @param _balanceA     Correct balance for party A.
     * @param _balanceB     Correct balance for party B.
     * @param _nonce        Higher nonce than the challenger's.
     * @param _signature    Other party's signature of this state.
     */
    function counterDispute(
        bytes32 _channelId,
        uint256 _balanceA,
        uint256 _balanceB,
        uint256 _nonce,
        bytes calldata _signature
    ) external whenNotPaused onlyChannelParty(_channelId) {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.CLOSING) revert InvalidChannelStatus(ch.status);

        ChannelDispute storage d = disputes[_channelId];
        if (block.timestamp > d.expiresAt) revert ChallengePeriodExpired();
        if (_nonce <= d.challengeNonce) revert NonceTooLow(_nonce, d.challengeNonce);

        uint256 totalDeposit = ch.depositA + ch.depositB;
        if (_balanceA + _balanceB != totalDeposit) revert InvalidBalances();

        // Verify signature
        bytes32 stateHash = keccak256(
            abi.encodePacked(_channelId, _balanceA, _balanceB, _nonce, "STATE")
        );
        bytes32 ethSignedHash = stateHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(_signature);

        address counterparty = msg.sender == ch.partyA ? ch.partyB : ch.partyA;
        if (signer != counterparty) revert InvalidSignature();

        // Update dispute with higher nonce state
        d.challengeNonce = _nonce;
        d.challengeBalanceA = _balanceA;
        d.challengeBalanceB = _balanceB;
        d.challenger = msg.sender;
        d.expiresAt = block.timestamp + ch.challengePeriod; // Reset challenge period

        ch.balanceA = _balanceA;
        ch.balanceB = _balanceB;
        ch.nonce = _nonce;

        emit DisputeCountered(_channelId, msg.sender, _nonce);
    }

    /**
     * @notice Finalizes a unilateral close after the challenge period expires.
     * @param _channelId Channel to finalize.
     */
    function finalizeClose(
        bytes32 _channelId
    ) external whenNotPaused nonReentrant {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.CLOSING) revert InvalidChannelStatus(ch.status);

        ChannelDispute storage d = disputes[_channelId];
        if (block.timestamp < d.expiresAt) revert ChallengeNotExpired();

        d.resolved = true;

        _settleChannel(ch, d.challengeBalanceA, d.challengeBalanceB, d.challengeNonce);

        emit DisputeResolved(_channelId, d.challengeBalanceA, d.challengeBalanceB);
    }

    // ──────────────────────────────────────────────────────────────
    // External — HTLC (Hash Time-Locked Contracts)
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates an HTLC for a conditional payment within a channel.
     * @dev Used for multi-hop routing: the sender locks funds that can only
     *      be claimed by revealing the preimage of the hash lock.
     * @param _channelId Channel containing the HTLC.
     * @param _amount    Amount locked in the HTLC.
     * @param _hashLock  keccak256 of the secret preimage.
     * @param _timelock  Expiry timestamp for the HTLC.
     * @return htlcId    Unique HTLC identifier.
     */
    function createHTLC(
        bytes32 _channelId,
        uint256 _amount,
        bytes32 _hashLock,
        uint256 _timelock
    ) external whenNotPaused onlyChannelParty(_channelId) returns (bytes32 htlcId) {
        Channel storage ch = channels[_channelId];
        if (ch.status != ChannelStatus.ACTIVE) revert InvalidChannelStatus(ch.status);
        if (_amount == 0) revert ZeroAmount();
        if (_timelock < block.timestamp + MIN_HTLC_TIMELOCK) revert InvalidTimelock();
        if (_timelock > block.timestamp + MAX_HTLC_TIMELOCK) revert InvalidTimelock();

        // Verify sender has sufficient balance in the channel
        uint256 senderBalance = msg.sender == ch.partyA ? ch.balanceA : ch.balanceB;
        if (_amount > senderBalance) revert InsufficientDeposit();

        // Lock funds
        if (msg.sender == ch.partyA) {
            ch.balanceA -= _amount;
        } else {
            ch.balanceB -= _amount;
        }

        address receiver = msg.sender == ch.partyA ? ch.partyB : ch.partyA;

        htlcId = keccak256(
            abi.encodePacked(_channelId, msg.sender, _amount, _hashLock, block.timestamp, htlcNonce++)
        );

        htlcs[htlcId] = HTLC({
            htlcId: htlcId,
            channelId: _channelId,
            sender: msg.sender,
            receiver: receiver,
            amount: _amount,
            hashLock: _hashLock,
            timelock: _timelock,
            status: HTLCStatus.ACTIVE,
            createdAt: block.timestamp
        });

        channelHTLCs[_channelId].push(htlcId);

        emit HTLCCreated(htlcId, _channelId, msg.sender, _amount, _hashLock, _timelock);
    }

    /**
     * @notice Claims an HTLC by revealing the preimage.
     * @param _htlcId   HTLC to claim.
     * @param _preimage Secret preimage whose hash matches the hash lock.
     */
    function claimHTLC(
        bytes32 _htlcId,
        bytes32 _preimage
    ) external whenNotPaused {
        HTLC storage h = htlcs[_htlcId];
        if (h.createdAt == 0) revert HTLCNotFound();
        if (h.status != HTLCStatus.ACTIVE) revert InvalidHTLCStatus(h.status);
        if (block.timestamp > h.timelock) revert HTLCExpired();
        if (keccak256(abi.encodePacked(_preimage)) != h.hashLock) revert InvalidPreimage();

        h.status = HTLCStatus.CLAIMED;

        // Credit receiver's channel balance
        Channel storage ch = channels[h.channelId];
        if (h.receiver == ch.partyA) {
            ch.balanceA += h.amount;
        } else {
            ch.balanceB += h.amount;
        }

        emit HTLCClaimed(_htlcId, _preimage);
    }

    /**
     * @notice Refunds an expired HTLC back to the sender.
     * @param _htlcId HTLC to refund.
     */
    function refundHTLC(bytes32 _htlcId) external whenNotPaused {
        HTLC storage h = htlcs[_htlcId];
        if (h.createdAt == 0) revert HTLCNotFound();
        if (h.status != HTLCStatus.ACTIVE) revert InvalidHTLCStatus(h.status);
        if (block.timestamp <= h.timelock) revert HTLCNotExpired();

        h.status = HTLCStatus.REFUNDED;

        // Return funds to sender's channel balance
        Channel storage ch = channels[h.channelId];
        if (h.sender == ch.partyA) {
            ch.balanceA += h.amount;
        } else {
            ch.balanceB += h.amount;
        }

        emit HTLCRefunded(_htlcId);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Multi-Hop Routing
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Registers a multi-hop routing path through intermediary channels.
     * @dev Called by routing nodes to establish a payment path. Each hop
     *      has an associated channel and routing fee.
     * @param _channelIds     Ordered array of channel IDs forming the path.
     * @param _intermediaries Addresses of routing nodes.
     * @param _amount         Payment amount.
     * @return pathId         Unique path identifier.
     */
    function registerRoutingPath(
        bytes32[] calldata _channelIds,
        address[] calldata _intermediaries,
        uint256 _amount
    ) external whenNotPaused onlyRole(ROUTER_ROLE) returns (bytes32 pathId) {
        if (_channelIds.length == 0) revert ZeroAmount();
        if (_channelIds.length > MAX_ROUTING_HOPS) revert RoutingPathTooLong();
        require(
            _channelIds.length == _intermediaries.length + 1,
            "PaymentChannels: invalid path structure"
        );

        uint256 totalFees;
        for (uint256 i; i < _channelIds.length;) {
            Channel storage ch = channels[_channelIds[i]];
            if (ch.openedAt == 0) revert ChannelNotFound();
            if (ch.status != ChannelStatus.ACTIVE) revert InvalidChannelStatus(ch.status);
            totalFees += (_amount * ch.routingFeeBps) / 10_000;

            unchecked { ++i; }
        }

        pathId = keccak256(
            abi.encodePacked(msg.sender, _amount, block.timestamp, routingNonce++)
        );

        routingPaths[pathId] = RoutingPath({
            pathId: pathId,
            channelIds: _channelIds,
            intermediaries: _intermediaries,
            totalFees: totalFees,
            amount: _amount,
            createdAt: block.timestamp,
            completed: false
        });

        emit RoutingPathCreated(pathId, _channelIds.length, _amount, totalFees);
    }

    /**
     * @notice Marks a routing path as completed.
     * @param _pathId Path to mark as completed.
     */
    function completeRoutingPath(bytes32 _pathId) external onlyRole(ROUTER_ROLE) {
        RoutingPath storage path = routingPaths[_pathId];
        require(path.createdAt > 0, "PaymentChannels: path not found");
        require(!path.completed, "PaymentChannels: already completed");

        path.completed = true;
        emit RoutingPathCompleted(_pathId);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Watchtower Management
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Registers as a watchtower for channel monitoring.
     * @param _bountyBps Bounty rate in basis points for successful disputes.
     */
    function registerWatchtower(
        uint256 _bountyBps
    ) external payable whenNotPaused nonReentrant {
        if (watchtowers[msg.sender].registeredAt != 0) revert WatchtowerAlreadyRegistered();
        if (msg.value < MIN_WATCHTOWER_STAKE) revert InsufficientStake();
        if (_bountyBps > MAX_ROUTING_FEE_BPS) revert InvalidFee();

        watchtowers[msg.sender] = Watchtower({
            operator: msg.sender,
            stake: msg.value,
            bountyBps: _bountyBps,
            channelsMonitored: 0,
            disputesRaised: 0,
            active: true,
            registeredAt: block.timestamp
        });

        _grantRole(WATCHTOWER_ROLE, msg.sender);

        emit WatchtowerRegistered(msg.sender, msg.value, _bountyBps);
    }

    /**
     * @notice Deregisters a watchtower and returns stake.
     */
    function deregisterWatchtower() external nonReentrant {
        Watchtower storage wt = watchtowers[msg.sender];
        if (wt.registeredAt == 0) revert WatchtowerNotFound();

        uint256 stakeToReturn = wt.stake;
        wt.active = false;
        wt.stake = 0;

        _revokeRole(WATCHTOWER_ROLE, msg.sender);

        if (stakeToReturn > 0) {
            (bool ok, ) = msg.sender.call{value: stakeToReturn}("");
            require(ok, "PaymentChannels: stake return failed");
        }

        emit WatchtowerDeregistered(msg.sender, stakeToReturn);
    }

    /**
     * @notice Assigns a watchtower to monitor a channel.
     * @param _channelId  Channel to monitor.
     * @param _watchtower Watchtower address.
     */
    function assignWatchtower(
        bytes32 _channelId,
        address _watchtower
    ) external onlyChannelParty(_channelId) whenNotPaused {
        if (channels[_channelId].openedAt == 0) revert ChannelNotFound();
        Watchtower storage wt = watchtowers[_watchtower];
        if (!wt.active) revert WatchtowerNotFound();

        channelWatchtowers[_channelId].push(_watchtower);
        wt.channelsMonitored++;

        emit WatchtowerAssigned(_channelId, _watchtower);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Batch Operations
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Opens multiple channels in a single transaction.
     * @param _counterparties Array of counterparty addresses.
     * @param _token          Shared settlement token.
     * @param _deposits       Array of initial deposits.
     * @param _challengePeriod Shared challenge period.
     * @param _routingFeeBps  Shared routing fee.
     * @return channelIds     Array of created channel IDs.
     */
    function batchOpenChannels(
        address[] calldata _counterparties,
        address _token,
        uint256[] calldata _deposits,
        uint256 _challengePeriod,
        uint256 _routingFeeBps
    ) external whenNotPaused nonReentrant returns (bytes32[] memory channelIds) {
        uint256 count = _counterparties.length;
        if (count == 0) revert ZeroAmount();
        if (count > MAX_BATCH_SIZE) revert BatchTooLarge();
        require(count == _deposits.length, "PaymentChannels: array mismatch");
        if (!supportedTokens[_token]) revert UnsupportedToken();
        _validateChannelParams(_challengePeriod, _routingFeeBps);

        channelIds = new bytes32[](count);
        uint256 totalDeposit;

        for (uint256 i; i < count;) {
            if (!kycVerified[msg.sender] || !kycVerified[_counterparties[i]]) revert KYCRequired();
            if (_deposits[i] == 0) revert ZeroAmount();

            bytes32 id = keccak256(
                abi.encodePacked(msg.sender, _counterparties[i], _token, block.timestamp, channelNonce++)
            );
            channelIds[i] = id;

            channels[id] = Channel({
                channelId: id,
                partyA: msg.sender,
                partyB: _counterparties[i],
                token: _token,
                depositA: _deposits[i],
                depositB: 0,
                balanceA: _deposits[i],
                balanceB: 0,
                status: ChannelStatus.OPEN,
                nonce: 0,
                openedAt: block.timestamp,
                closingAt: 0,
                closedAt: 0,
                challengePeriod: _challengePeriod,
                routingFeeBps: _routingFeeBps
            });

            userChannels[msg.sender].push(id);
            userChannels[_counterparties[i]].push(id);
            totalDeposit += _deposits[i];

            emit ChannelOpened(id, msg.sender, _counterparties[i], _token, _deposits[i], _challengePeriod);

            unchecked { ++i; }
        }

        IERC20(_token).safeTransferFrom(msg.sender, address(this), totalDeposit);

        emit ChannelBatchOpened(count);
    }

    // ──────────────────────────────────────────────────────────────
    // View Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Returns a channel record.
    function getChannel(bytes32 _channelId) external view returns (Channel memory) {
        return channels[_channelId];
    }

    /// @notice Returns the dispute record for a channel.
    function getDispute(bytes32 _channelId) external view returns (ChannelDispute memory) {
        return disputes[_channelId];
    }

    /// @notice Returns an HTLC record.
    function getHTLC(bytes32 _htlcId) external view returns (HTLC memory) {
        return htlcs[_htlcId];
    }

    /// @notice Returns all HTLC IDs for a channel.
    function getChannelHTLCs(bytes32 _channelId) external view returns (bytes32[] memory) {
        return channelHTLCs[_channelId];
    }

    /// @notice Returns all channel IDs for a user.
    function getUserChannels(address _user) external view returns (bytes32[] memory) {
        return userChannels[_user];
    }

    /// @notice Returns a watchtower record.
    function getWatchtower(address _operator) external view returns (Watchtower memory) {
        return watchtowers[_operator];
    }

    /// @notice Returns assigned watchtowers for a channel.
    function getChannelWatchtowers(bytes32 _channelId) external view returns (address[] memory) {
        return channelWatchtowers[_channelId];
    }

    /// @notice Returns a routing path record.
    function getRoutingPath(bytes32 _pathId) external view returns (RoutingPath memory) {
        return routingPaths[_pathId];
    }

    /// @notice Computes the state hash for off-chain signing.
    function computeStateHash(
        bytes32 _channelId,
        uint256 _balanceA,
        uint256 _balanceB,
        uint256 _nonce,
        string calldata _type
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encodePacked(_channelId, _balanceA, _balanceB, _nonce, _type)
        );
    }

    // ──────────────────────────────────────────────────────────────
    // Admin Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Updates KYC verification status for a party.
    function setKYCStatus(address _party, bool _verified) external onlyRole(ADMIN_ROLE) {
        if (_party == address(0)) revert ZeroAddress();
        kycVerified[_party] = _verified;
        emit KYCStatusUpdated(_party, _verified);
    }

    /// @notice Batch updates KYC verification status.
    function batchSetKYCStatus(
        address[] calldata _parties,
        bool[] calldata _statuses
    ) external onlyRole(ADMIN_ROLE) {
        require(_parties.length == _statuses.length, "PaymentChannels: array mismatch");
        for (uint256 i; i < _parties.length;) {
            if (_parties[i] == address(0)) revert ZeroAddress();
            kycVerified[_parties[i]] = _statuses[i];
            emit KYCStatusUpdated(_parties[i], _statuses[i]);
            unchecked { ++i; }
        }
    }

    /// @notice Adds or removes a supported settlement token.
    function setSupportedToken(address _token, bool _supported) external onlyRole(ADMIN_ROLE) {
        if (_token == address(0)) revert ZeroAddress();
        supportedTokens[_token] = _supported;
        emit TokenSupported(_token, _supported);
    }

    /// @notice Sets the NoblePay contract reference.
    function setNoblePayContract(address _noblepay) external onlyRole(ADMIN_ROLE) {
        if (_noblepay == address(0)) revert ZeroAddress();
        noblePayContract = _noblepay;
    }

    /// @notice Emergency pause.
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /// @notice Resume operations.
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ──────────────────────────────────────────────────────────────
    // Internal Helpers
    // ──────────────────────────────────────────────────────────────

    /**
     * @dev Validates channel parameters shared by openChannel and batchOpenChannels.
     * @param _challengePeriod Dispute challenge window in seconds.
     * @param _routingFeeBps   Fee for routing through this channel.
     */
    function _validateChannelParams(uint256 _challengePeriod, uint256 _routingFeeBps) internal pure {
        if (_challengePeriod < MIN_CHALLENGE_PERIOD || _challengePeriod > MAX_CHALLENGE_PERIOD) {
            revert InvalidChallengePeriod();
        }
        if (_routingFeeBps > MAX_ROUTING_FEE_BPS) revert InvalidFee();
    }

    /**
     * @dev Settles a channel by transferring final balances to both parties.
     * @param ch             Channel storage reference.
     * @param _finalBalanceA Final balance for party A.
     * @param _finalBalanceB Final balance for party B.
     * @param _nonce         Final state nonce.
     */
    function _settleChannel(
        Channel storage ch,
        uint256 _finalBalanceA,
        uint256 _finalBalanceB,
        uint256 _nonce
    ) internal {
        ch.status = ChannelStatus.CLOSED;
        ch.closedAt = block.timestamp;
        ch.balanceA = _finalBalanceA;
        ch.balanceB = _finalBalanceB;
        ch.nonce = _nonce;

        // Apply protocol fee
        uint256 totalFee;
        uint256 feeA;
        uint256 feeB;

        if (protocolFeeBps > 0) {
            feeA = (_finalBalanceA * protocolFeeBps) / 10_000;
            feeB = (_finalBalanceB * protocolFeeBps) / 10_000;
            totalFee = feeA + feeB;
        }

        uint256 payA = _finalBalanceA - feeA;
        uint256 payB = _finalBalanceB - feeB;

        if (payA > 0) {
            IERC20(ch.token).safeTransfer(ch.partyA, payA);
        }
        if (payB > 0) {
            IERC20(ch.token).safeTransfer(ch.partyB, payB);
        }
        if (totalFee > 0) {
            IERC20(ch.token).safeTransfer(protocolTreasury, totalFee);
        }

        emit ChannelClosed(ch.channelId, _finalBalanceA, _finalBalanceB);
    }

    /// @notice Allows the contract to receive native tokens for watchtower stakes.
    receive() external payable {}
}

